# "Frozen" splits into Frozen Boneless / Frozen Bone-in (7 days from defrost start),
# and fresh (never frozen) versions are added: Fresh Boneless 4 days, Fresh Bone-in 3 days,
# counted from time in. Notes "Frozen" / "Fresh" tell the two apart on cards and slips.
BONEIN = {"Bone-in Wings"}
CHICKEN = ["Fillet", "Nuggets/LTO", "Boneless Wings", "Spicy Tenders", "Mild Tenders", "Bone-in Wings"]


def split(apps, schema_editor):
    Product = apps.get_model("slips", "Product")
    for p in Product.objects.filter(group="frozen"):
        p.group = "frozen_bonein" if p.name in BONEIN else "frozen_boneless"
        p.note = p.note or "Frozen"
        p.save()
    for i, name in enumerate(CHICKEN):
        bone_in = name in BONEIN
        Product.objects.get_or_create(
            name=name, note="Fresh",
            defaults=dict(
                group="fresh_bonein" if bone_in else "fresh_boneless", basis="time_in",
                duration_value=3 if bone_in else 4, duration_unit="days", sort_order=36 + i,
            ),
        )


def merge(apps, schema_editor):
    Product = apps.get_model("slips", "Product")
    Product.objects.filter(group__in=["fresh_bonein", "fresh_boneless"], note="Fresh", slips__isnull=True).delete()
    Product.objects.filter(group__in=["frozen_bonein", "frozen_boneless"]).update(group="frozen")
    Product.objects.filter(group="frozen", note="Frozen").update(note="")


